function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each value is an integer between -100 and 100.';
  if (!Number.isInteger(k) || k < 1 || k > 10000) return 'k is between 1 and 10^4.';
  return null;
}

