function largestSumAfterKNegations(nums, k) {
  nums.sort((a, b) => a - b);
  let flipsLeft = k;
  let i = 0;
  while (flipsLeft > 0 && i < nums.length && nums[i] < 0) {
    nums[i] = -nums[i];
    flipsLeft--;
    i++;
  }

  let sum = 0;
  let smallest = Infinity;
  for (const value of nums) {
    sum += value;
    smallest = Math.min(smallest, value);
  }

  if (flipsLeft % 2 === 1) {
    sum -= 2 * smallest;
  }
  return sum;
}

