function largestSumAfterKNegations(nums, k) {
  // Only the parity of each index's flips matters. A set of indices flipped an odd number of times is reachable
  // exactly when its size is at most k and has the same parity as k (the spare flips cancel out in pairs).
  const n = nums.length;
  let best = -Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let size = 0, total = 0;
    for (let j = 0; j < n; j++) {
      if (mask & (1 << j)) { size++; total -= nums[j]; } else total += nums[j];
    }
    if (size <= k && (k - size) % 2 === 0) best = Math.max(best, total);
  }
  return best;
}

