function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const span = rand() < 0.5 ? 5 : 100;
    const nums = Array.from({ length: n }, () => int(-span, span));
    return [nums, int(1, 12)];
  }
  const n = 2000;
  const negativeBias = rand();
  const nums = Array.from({ length: n }, () => rand() < negativeBias ? int(-100, -1) : int(0, 100));
  const k = rand() < 0.5 ? int(1, n) : int(1, 10000);
  return [nums, k];
}
